-- Library membership and ownership are independent, keyed by stable account ID.
-- Availability remains authoritative in media.ready/deleting/deleted.
CREATE TABLE library_owners(account_id TEXT NOT NULL,media_id TEXT NOT NULL REFERENCES media(id) ON DELETE CASCADE,PRIMARY KEY(account_id,media_id)) WITHOUT ROWID;
CREATE INDEX library_owners_media ON library_owners(media_id,account_id);
CREATE TABLE library_entries(account_id TEXT NOT NULL,media_id TEXT NOT NULL REFERENCES media(id) ON DELETE CASCADE,position BIGINT NOT NULL,PRIMARY KEY(account_id,media_id)) WITHOUT ROWID;
CREATE INDEX library_entries_media ON library_entries(media_id,account_id);
CREATE UNIQUE INDEX library_entries_order ON library_entries(account_id,position);
CREATE TABLE library_recents(account_id TEXT NOT NULL,media_id TEXT NOT NULL REFERENCES media(id) ON DELETE CASCADE,used INTEGER NOT NULL,PRIMARY KEY(account_id,media_id)) WITHOUT ROWID;
CREATE INDEX library_recents_order ON library_recents(account_id,used DESC,media_id);
CREATE TABLE library_storage(id INTEGER PRIMARY KEY CHECK(id=1),bytes INTEGER NOT NULL CHECK(bytes>=0),objects INTEGER NOT NULL CHECK(objects>=0));
INSERT INTO library_storage VALUES(1,0,0);
CREATE INDEX media_library_backlog ON media(COALESCE(unreferenced,created)) WHERE conversation='@library' AND (deleting=1 OR deleted=1) AND (deleted=0 OR staging_clean=0);
CREATE TRIGGER library_storage_insert AFTER INSERT ON media WHEN (CASE WHEN NEW.conversation='@library' AND NEW.deleted=0 AND NEW.deleting=1 THEN NEW.size ELSE 0 END + CASE WHEN NEW.conversation='@library' AND NEW.staging_clean=0 AND (NEW.deleting=1 OR NEW.deleted=1) THEN NEW.size ELSE 0 END)!=0 OR (CASE WHEN NEW.conversation='@library' AND NEW.deleted=0 AND NEW.deleting=1 THEN 1 ELSE 0 END + CASE WHEN NEW.conversation='@library' AND NEW.staging_clean=0 AND (NEW.deleting=1 OR NEW.deleted=1) THEN 1 ELSE 0 END)!=0 BEGIN
 UPDATE library_storage SET bytes=bytes+(CASE WHEN NEW.conversation='@library' AND NEW.deleted=0 AND NEW.deleting=1 THEN NEW.size ELSE 0 END + CASE WHEN NEW.conversation='@library' AND NEW.staging_clean=0 AND (NEW.deleting=1 OR NEW.deleted=1) THEN NEW.size ELSE 0 END)-0,objects=objects+(CASE WHEN NEW.conversation='@library' AND NEW.deleted=0 AND NEW.deleting=1 THEN 1 ELSE 0 END + CASE WHEN NEW.conversation='@library' AND NEW.staging_clean=0 AND (NEW.deleting=1 OR NEW.deleted=1) THEN 1 ELSE 0 END)-0 WHERE id=1;
END;
CREATE TRIGGER library_storage_update AFTER UPDATE OF conversation,size,deleting,deleted,staging_clean ON media WHEN (CASE WHEN NEW.conversation='@library' AND NEW.deleted=0 AND NEW.deleting=1 THEN NEW.size ELSE 0 END + CASE WHEN NEW.conversation='@library' AND NEW.staging_clean=0 AND (NEW.deleting=1 OR NEW.deleted=1) THEN NEW.size ELSE 0 END)!=(CASE WHEN OLD.conversation='@library' AND OLD.deleted=0 AND OLD.deleting=1 THEN OLD.size ELSE 0 END + CASE WHEN OLD.conversation='@library' AND OLD.staging_clean=0 AND (OLD.deleting=1 OR OLD.deleted=1) THEN OLD.size ELSE 0 END) OR (CASE WHEN NEW.conversation='@library' AND NEW.deleted=0 AND NEW.deleting=1 THEN 1 ELSE 0 END + CASE WHEN NEW.conversation='@library' AND NEW.staging_clean=0 AND (NEW.deleting=1 OR NEW.deleted=1) THEN 1 ELSE 0 END)!=(CASE WHEN OLD.conversation='@library' AND OLD.deleted=0 AND OLD.deleting=1 THEN 1 ELSE 0 END + CASE WHEN OLD.conversation='@library' AND OLD.staging_clean=0 AND (OLD.deleting=1 OR OLD.deleted=1) THEN 1 ELSE 0 END) BEGIN
 UPDATE library_storage SET bytes=bytes+(CASE WHEN NEW.conversation='@library' AND NEW.deleted=0 AND NEW.deleting=1 THEN NEW.size ELSE 0 END + CASE WHEN NEW.conversation='@library' AND NEW.staging_clean=0 AND (NEW.deleting=1 OR NEW.deleted=1) THEN NEW.size ELSE 0 END)-(CASE WHEN OLD.conversation='@library' AND OLD.deleted=0 AND OLD.deleting=1 THEN OLD.size ELSE 0 END + CASE WHEN OLD.conversation='@library' AND OLD.staging_clean=0 AND (OLD.deleting=1 OR OLD.deleted=1) THEN OLD.size ELSE 0 END),objects=objects+(CASE WHEN NEW.conversation='@library' AND NEW.deleted=0 AND NEW.deleting=1 THEN 1 ELSE 0 END + CASE WHEN NEW.conversation='@library' AND NEW.staging_clean=0 AND (NEW.deleting=1 OR NEW.deleted=1) THEN 1 ELSE 0 END)-(CASE WHEN OLD.conversation='@library' AND OLD.deleted=0 AND OLD.deleting=1 THEN 1 ELSE 0 END + CASE WHEN OLD.conversation='@library' AND OLD.staging_clean=0 AND (OLD.deleting=1 OR OLD.deleted=1) THEN 1 ELSE 0 END) WHERE id=1;
END;
CREATE TRIGGER library_storage_delete AFTER DELETE ON media WHEN 0!=(CASE WHEN OLD.conversation='@library' AND OLD.deleted=0 AND OLD.deleting=1 THEN OLD.size ELSE 0 END + CASE WHEN OLD.conversation='@library' AND OLD.staging_clean=0 AND (OLD.deleting=1 OR OLD.deleted=1) THEN OLD.size ELSE 0 END) OR 0!=(CASE WHEN OLD.conversation='@library' AND OLD.deleted=0 AND OLD.deleting=1 THEN 1 ELSE 0 END + CASE WHEN OLD.conversation='@library' AND OLD.staging_clean=0 AND (OLD.deleting=1 OR OLD.deleted=1) THEN 1 ELSE 0 END) BEGIN
 UPDATE library_storage SET bytes=bytes+0-(CASE WHEN OLD.conversation='@library' AND OLD.deleted=0 AND OLD.deleting=1 THEN OLD.size ELSE 0 END + CASE WHEN OLD.conversation='@library' AND OLD.staging_clean=0 AND (OLD.deleting=1 OR OLD.deleted=1) THEN OLD.size ELSE 0 END),objects=objects+0-(CASE WHEN OLD.conversation='@library' AND OLD.deleted=0 AND OLD.deleting=1 THEN 1 ELSE 0 END + CASE WHEN OLD.conversation='@library' AND OLD.staging_clean=0 AND (OLD.deleting=1 OR OLD.deleted=1) THEN 1 ELSE 0 END) WHERE id=1;
END;
